#include <iostream>
#include <iomanip>
#include <algorithm>
#include <numeric>

// Legacy C preprocessor macros
#define CUBE_VOLUME(x)  ((x) * (x) * (x))
#define SUM(x, y)       ((x) + (y))
#define MINIMUM2(a, b)  (((a) < (b)) ? (a) : (b))
#define MINIMUM3(a, b, c) (MINIMUM2(MINIMUM2((a), (b)), (c)))

// Modern C++17 alternatives
template <typename T>
constexpr T modernCube(T x) noexcept {
    return x * x * x;
}

template <typename T>
constexpr T modernMin3(T a, T b, T c) noexcept {
    return std::min({a, b, c});
}

int main() {
    int x = 6;
    int y = 7;
    int z = 3;

    // Using SUM macro as in Exercise 13.5
    std::cout << "The sum of x and y is " << SUM(x, y) << "\n";

    // Evaluating precedence with CUBE_VOLUME
    std::cout << "CUBE_VOLUME(1 + 2) = " << CUBE_VOLUME(1 + 2) << "\n";
    std::cout << "modernCube(1 + 2) = " << modernCube(1 + 2) << "\n";

    // Nested minimum
    std::cout << "MINIMUM2(" << x << ", " << y << ") = " << MINIMUM2(x, y) << "\n";
    std::cout << "MINIMUM3(" << x << ", " << y << ", " << z << ") = " << MINIMUM3(x, y, z) << "\n";
    std::cout << "modernMin3(" << x << ", " << y << ", " << z << ") = " << modernMin3(x, y, z) << "\n";

    return 0;
}
